def _ensure_branch_exists(self, branch: str) -> None:
        """Ensure a branch exists (fetch from remote if needed)."""
        # Check local first
        result = self._git("rev-parse", "--verify", branch, check=False)
        if result is not None:
            return
        # Try fetching from origin and creating the local branch from FETCH_HEAD
        if self._git("fetch", "origin", branch, check=False) is not None:
            self._git("branch", branch, "FETCH_HEAD", check=False)

